!function(e){function n(n){for(var t,a,o=n[0],p=n[1],c=n[2],s=0,g=[];s<o.length;s++)a=o[s],Object.prototype.hasOwnProperty.call(m,a)&&m[a]&&g.push(m[a][0]),m[a]=0;for(t in p)Object.prototype.hasOwnProperty.call(p,t)&&(e[t]=p[t]);for(d&&d(n);g.length;)g.shift()();return i.push.apply(i,c||[]),r()}function r(){for(var e,n=0;n<i.length;n++){for(var r,a=i[n],o=!0,p=1;p<a.length;p++)r=a[p],0!==m[r]&&(o=!1);o&&(i.splice(n--,1),e=t(t.s=a[0]))}return e}function t(n){if(a[n])return a[n].exports;var r=a[n]={i:n,l:!1,exports:{}};return e[n].call(r.exports,r,r.exports,t),r.l=!0,r.exports}var a={},m={39:0},i=[];t.m=e,t.c=a,t.d=function(e,n,r){t.o(e,n)||Object.defineProperty(e,n,{enumerable:!0,get:r})},t.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},t.t=function(e,n){if(1&n&&(e=t(e)),8&n)return e;if(4&n&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(t.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&n&&"string"!=typeof e)for(var a in e)t.d(r,a,function(n){return e[n]}.bind(null,a));return r},t.n=function(e){var n=e&&e.__esModule?function(){return e.default}:function(){return e};return t.d(n,"a",n),n},t.o=function(e,n){return Object.prototype.hasOwnProperty.call(e,n)},t.p="";var o=window.webpackJsonp=window.webpackJsonp||[],p=o.push.bind(o);o.push=n,o=o.slice();for(var c=0;c<o.length;c++)n(o[c]);var d=p;i.push([202,0]),r()}({202:function(e,n,r){"use strict";r.r(n);var t=r(0);Object(t.a)("de","army",r(203),r(1))},203:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"火炮","link":"de_army#de_army_cannon"}],"model":"105mm Ie FH18型榴弹炮","description":"<p>105mm Ie FH18型榴弹炮（Ie FH在德语中的意思是：近程野战榴弹炮）是二战德国国防军一种标准制式火炮武器，该炮在1939年正式在德军中服役，在二战各战场上跟随德军战斗到二战结束。</p><p>105mm Ie FH18榴弹炮性能比较优秀，它的炮膛机构简单，配备有液压缓冲系统，在作曲射压制时，可以灵活调节火炮弹道，而在近距离与坦克对抗时，可以改为直射瞄准，成为反坦克火炮，是德军在战场上又一种有效的杀敌火器。</p><p>105mm Ie FH18榴弹炮是德国在二战期间产量较多的一种火炮，二战期间共生产了近7000门（注：该炮有很多改型，因此105榴弹炮的产量应远不止此数）。二战爆发时，德军已装备有2000多门105mm Ie FH18榴弹炮，到了1942初，德国陆军的105mm Ie FH18榴弹炮拥有量已达6155门。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_cannonFH18_11.jpg","description":"<h6>105mm Ie FH18型榴弹炮</h6><p></p><p>技术数据：</p><p>火炮口径：105mm；</p><p>火炮长：2.941米，宽：1.98米，高：1.88米；</p><p>炮管长：2.94米；</p><p>火炮重：战斗2.04吨，运输3.49吨；</p><p>火炮射界（水平方向）：56度，火炮射角（垂直方向）：-5～+42度；</p><p>射速：6～8发/分钟；</p><p>最大射程：12325米，有效射程：10675米。</p>","caption":""}],"part2title":"战场上的105mm Ie FH18型榴弹炮","part2description":"","part2content":[{"image":"imgs/de/army/de_army_cannonFH18_21.jpg","description":"德军一门准备射击的105mm Ie FH18榴弹炮，炮组成员将炮设置在树林的最边缘，是为了借树林的掩护达到隐蔽的目的。","caption":""},{"image":"imgs/de/army/de_army_cannonFH18_22.jpg","description":"德军一门正在城市作战的105mm Ie FH18榴弹炮，在在这里，为了不遮挡视线，冒着暴露的危险，炮组成员只能将榴弹炮阵地设置在城市街道上。请注意地上废弃的木板条包装箱，这是用来装炮弹的。","caption":""},{"image":"imgs/de/army/de_army_cannonFH18_23.jpg","description":"二战东线苏联战场，一门安置在野战战场草丛中的德军105mm Ie FH18榴弹炮正在对着瞄准目标进行直接射击；该炮虽是榴弹炮，但亦可使用穿甲弹直射作反坦克炮用，其发射的加强型穿甲弹重14公斤，出膛初速度为470米/秒，穿甲性能为：100米距离可击穿84mm厚装甲，1500米距离可击穿49mm厚装甲。注意，图中两名炮组成员正在观察射击的效果。散布在地上的是各种用于弹药的运输容器，耗费弹药之多，可见战斗的激烈。此外，该炮装有带橡胶轮辋的铸造车轮，表明它是用汽车牵引运输的。","caption":""},{"image":"imgs/de/army/de_army_cannonFH18_24.jpg","description":"二战东线战役初期的苏联战场，冬天，安置在雪地中的德军一门105mm Ie FH18榴弹炮，一名炮兵正在装填炮弹。注意：这是一门改进型的105mm榴弹炮，该炮炮口加装了炮口制退器；为了增加射程，炮弹加大了装药量，而炮口制动器可以帮助消散炮弹出膛时的反冲力。","caption":""},{"image":"imgs/de/army/de_army_cannonFH18_25.jpg","description":"1942年冬季，东线苏联战场，埃里希·冯·曼斯坦因将军访问了前线的德军炮兵部队，在105mm Ie FH18榴弹炮旁与炮兵们交谈。","caption":""},{"image":"imgs/de/army/de_army_cannonFH18_26.jpg","description":"二战东线苏联战场，德军的一个师属炮兵阵地，阵地上有多门105mm Ie FH18榴弹炮和弹药车。当时，在东线的每个德军装甲师都会配备一个拥有3个营的炮兵团，两个营装备105毫米炮，另一个营装备150毫米炮。一个营有3个炮连，每个炮连有4门炮。","caption":""},{"image":"imgs/de/army/de_army_cannonFH18_27.jpg","description":"二战西线意大利战场，德军将一门105mm Ie FH18榴弹炮架设在城市巷道中，并在炮身上放上许多树枝作掩护。","caption":""},{"image":"imgs/de/army/de_army_cannonFH18_28.jpg","description":"1944年末，东线战场的战斗已接近德国，一批武装党卫军装甲掷弹兵师的士兵正在德国紧急训练使用105mm Ie FH18榴弹炮，1945年初，该师参加了东波美拉尼亚战役的防御作战行动。","caption":""},{"image":"imgs/de/army/de_army_cannonFH18_29.jpg","description":"二战东线苏联战场，德军的一个105mm Ie FH18榴弹炮阵地，照片中的105mm榴弹炮正处在炮弹刚发射击后完全后坐的状态，此时6名炮兵在各自的炮位上各司其责。注意，一些炮兵胸前还挂着防毒面具罐。","caption":""},{"image":"imgs/de/army/de_army_cannonFH18_30.jpg","description":"图中为德军驾着马车牵引一门105mm Ie FH18榴弹炮在城市街道上行进，二战初期，由于机动牵引车的不足，德军很多火炮仍需用马或马车牵引运输。请注意，该马车应是专门作牵火炮用的，其车轴与火炮间有互联的制动装置，可由坐在马车的士兵控制。","caption":""},{"image":"imgs/de/army/de_army_cannonFH18_31.jpg","description":"1940年法国战役期间，一辆Sd.Kfz.251/4半履带装甲车正牵引一门105mm Ie FH18榴弹炮向前线进发。半履带车后的白色“K”表明它属于冯·克莱斯特装甲集团（Panzer Group von Kleist）下属的装甲师。","caption":""},{"image":"imgs/de/army/de_army_cannonFH18_32.jpg","description":"绘画：东线苏联战场，激战中的德军105mm Ie FH18榴弹炮阵地。","caption":""}]}')}});